body {
  margin: 0;
  background: #f3f4f6;
  color: #111827;
  font-family: Arial, sans-serif;
}

.print-button {
  display: block;
  margin: 10px auto;
  padding: 8px 14px;
  border: 0;
  background: #111827;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.receipt {
  width: 80mm;
  margin: 0 auto;
  padding: 5mm;
  box-sizing: border-box;
  background: white;
  font-size: 12px;
  line-height: 1.35;
}

.top {
  text-align: center;
}

.brand {
  font-size: 17px;
  font-weight: 900;
  text-transform: uppercase;
}

.title {
  margin-top: 4px;
  font-size: 14px;
  font-weight: 900;
  text-transform: uppercase;
}

.small {
  color: #4b5563;
  font-size: 10px;
}

.divider {
  border-top: 1px dashed #111827;
  margin: 9px 0;
}

.section-title {
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.line {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 4px 0;
}

.line span {
  color: #4b5563;
}

.line strong {
  text-align: right;
}

.grand {
  margin-top: 8px;
  padding: 7px 0;
  border-top: 2px solid #111827;
  font-size: 14px;
  font-weight: 900;
}

.warn {
  color: #b45309;
  font-weight: 900;
}

.danger {
  color: #dc2626;
  font-weight: 900;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  text-align: left;
  color: #4b5563;
  font-size: 10px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e5e7eb;
}

td {
  padding: 5px 0;
  vertical-align: top;
  border-bottom: 1px solid #f3f4f6;
}

.item-code {
  font-weight: 800;
}

.item-name {
  color: #4b5563;
  font-size: 10px;
}

.num {
  text-align: right;
  white-space: nowrap;
}

.qr-box {
  text-align: center;
}

.qr {
  width: 104px;
  height: 104px;
  image-rendering: pixelated;
}

.signature {
  font-size: 10px;
}

.signature-line {
  height: 22px;
  border-bottom: 1px solid #111827;
  margin-bottom: 8px;
}

@media print {
  body {
    background: white;
  }
  .print-button {
    display: none;
  }
  .receipt {
    margin: 0;
    padding: 4mm;
  }
}

