function val(value) {
  return String(value ?? "");
}
function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(3);
}
function line(label, value, cls = "") {
  return `
    <div class="line ${cls}">
      <span>${val(label)}</span>
      <strong>${val(value)}</strong>
    </div>
  `;
}
function reportTitle(type) {
  const map = {
    POS_OVERVIEW: "POS Overview",
    X_REPORT: "X Report",
    Z_REPORT: "Z Report",
    CASH_TRANSACTIONS: "Cash Transactions",
    PAYMENTS: "Payments",
    CLOSING: "Cash Closing"
  };
  return map[type] || "POS Report";
}
function qrPayload(model) {
  const overview = model.overview || {};
  return ["TYPE=" + val(model.type), "FROM=" + val(model.dateFrom), "TO=" + val(model.dateTo), "REGISTER=" + val(model.cashRegister), "TOTAL=" + money(overview.totalSales), "COUNT=" + val(overview.receiptCount)].join("&");
}
function qrSrc(payload) {
  return "https://api.qrserver.com/v1/create-qr-code/?size=120x120&ecc=M&margin=1&data=" + encodeURIComponent(payload);
}
function show(id, visible) {
  const el = document.getElementById(id);
  if (el) el.style.display = visible ? "block" : "none";
}
function renderOverview(model) {
  const o = model.overview || {};
  return [line("Receipts / Računi", o.receiptCount || 0), line("Cash / Gotovina", money(o.cashTotal)), line("Card / Kartice", money(o.cardTotal)), line("Bank / Banka", money(o.bankTotal)), line("Other / Ostalo", money(o.otherTotal)), line("Mixed / Miješano", money(o.mixedTotal)), line("Tax / Porez", money(o.totalTax)), line("Discount / Popust", money(o.totalDiscount)), line("Average / Prosjek", money(o.averageReceipt)), line("Total / Ukupno", money(o.totalSales), "grand")].join("");
}
function renderPayments(model) {
  const rows = model.payments || [];
  if (!rows.length) {
    return line("No payments", "-");
  }
  return rows.map(row => line(`${val(row.paymentMethod)} (${val(row.receiptCount)})`, money(row.totalAmount))).join("");
}
function renderTopItems(model) {
  const rows = model.topItems || [];
  if (!rows.length) {
    return `<tr><td colspan="3" class="item-name">No items</td></tr>`;
  }
  return rows.slice(0, 10).map(row => `
    <tr>
      <td>
        <div class="item-code">${val(row.productCode)}</div>
        <div class="item-name">${val(row.productName)}</div>
      </td>
      <td class="num">${qty(row.quantity)}</td>
      <td class="num">${money(row.totalAmount)}</td>
    </tr>
  `).join("");
}
function renderCashTransactions(model) {
  const rows = model.cashTransactions || [];
  if (!rows.length) {
    return line("No cash transactions", "-");
  }
  return rows.slice(0, 20).map(row => line(`${val(row.transactionType)} ${val(row.cashRegisterCode)}`, money(row.amount), Number(row.amount || 0) < 0 ? "danger" : "")).join("");
}
function renderClosing(model) {
  const rows = model.closings || [];
  if (!rows.length) {
    return line("No closing data", "-");
  }
  return rows.slice(0, 3).map(row => [line("Date / Datum", val(row.closingDate)), line("Register / Blagajna", `${val(row.cashRegisterCode)} ${val(row.cashRegisterName)}`), line("Opening / Početno", money(row.openingAmount)), line("Expected / Očekivano", money(row.expectedCashAmount)), line("Counted / Prebrojano", money(row.countedCashAmount)), line("Difference / Razlika", money(row.differenceAmount), Number(row.differenceAmount || 0) !== 0 ? "warn" : ""), line("Status", val(row.status)), `<div class="divider"></div>`].join("")).join("");
}
function render(model) {
  model = model || {};
  const type = model.type || "POS_OVERVIEW";
  document.getElementById("reportTitle").innerText = reportTitle(type);
  document.getElementById("period").innerText = `${val(model.dateFrom)} - ${val(model.dateTo)}`;
  document.getElementById("cashRegister").innerText = val(model.cashRegister || "All Registers");
  document.getElementById("printed").innerText = `Printed: ${val(model.printedAt)} ${model.printedBy ? "by " + val(model.printedBy) : ""}`;
  document.getElementById("overviewLines").innerHTML = renderOverview(model);
  document.getElementById("paymentLines").innerHTML = renderPayments(model);
  document.getElementById("topItemsBody").innerHTML = renderTopItems(model);
  document.getElementById("cashTransactionsLines").innerHTML = renderCashTransactions(model);
  document.getElementById("closingLines").innerHTML = renderClosing(model);
  show("overviewSection", ["POS_OVERVIEW", "X_REPORT", "Z_REPORT"].includes(type));
  show("paymentsSection", ["POS_OVERVIEW", "X_REPORT", "Z_REPORT", "PAYMENTS"].includes(type));
  show("topItemsSection", ["POS_OVERVIEW", "X_REPORT", "Z_REPORT"].includes(type));
  show("cashTransactionsSection", ["POS_OVERVIEW", "CASH_TRANSACTIONS"].includes(type));
  show("closingSection", ["POS_OVERVIEW", "Z_REPORT", "CLOSING"].includes(type));
  const payload = qrPayload(model);
  document.getElementById("qr").src = qrSrc(payload);
  document.getElementById("qrText").innerText = reportTitle(type);
  document.getElementById("printBtn").onclick = () => window.print();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

